<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';import {currentView,navigate} from './router';import {get,post,setCsrfToken} from './api/client';import Dashboard from './views/Dashboard.vue';import Predictions from './views/Predictions.vue';import Intraday from './views/Intraday.vue';import Tracking from './views/Tracking.vue';import Verifications from './views/Verifications.vue';import Stocks from './views/Stocks.vue';import Tasks from './views/Tasks.vue';import Login from './views/Login.vue';import ResetPassword from './views/ResetPassword.vue';import AccountAdmin from './views/AccountAdmin.vue';import Profile from './views/Profile.vue';
const user=ref(null),loading=ref(true),resetToken=ref(location.hash.startsWith('#reset=')?location.hash.slice(7):'');const views={dashboard:Dashboard,tasks:Tasks,predictions:Predictions,intraday:Intraday,tracking:Tracking,verifications:Verifications,stocks:Stocks,accounts:AccountAdmin,profile:Profile};const labels={dashboard:'市场总览',tasks:'任务中心',predictions:'预测候选',intraday:'盘中观察',tracking:'持仓跟踪',verifications:'收盘验证',stocks:'行情查询',accounts:'账号管理',profile:'个人中心'};const menuPermission={dashboard:'dashboard:view',tasks:'task:view',predictions:'prediction:view',intraday:'intraday:view',tracking:'prediction:view',verifications:'verification:view',stocks:'stock:view'};const allowedLabels=computed(()=>{if(!user.value)return{};const values={};for(const [key,label] of Object.entries(labels)){if(key==='profile'||(key==='accounts'&&user.value.permissions.some(p=>['user:view','role:view','session:manage','audit:view'].includes(p)))||user.value.permissions.includes(menuPermission[key]))values[key]=label}return values});const component=computed(()=>views[currentView.value]||Dashboard);
async function loadMe(){try{const value=await get('/auth/me');setCsrfToken(value.csrf_token);user.value=value;if(!allowedLabels.value[currentView.value])navigate(Object.keys(allowedLabels.value)[0]||'profile')}catch{user.value=null}finally{loading.value=false}}
function authenticated(value){user.value=value;navigate('dashboard')}async function logout(){try{await post('/auth/logout',{})}finally{setCsrfToken('');user.value=null;navigate('dashboard')}}function expired(){setCsrfToken('');user.value=null}function resetDone(){resetToken.value='';location.hash='';}
onMounted(()=>{window.addEventListener('auth-expired',expired);if(!resetToken.value)loadMe();else loading.value=false});onUnmounted(()=>window.removeEventListener('auth-expired',expired));
</script><template><div v-if="loading" class="auth-page"><div class="empty">正在检查登录状态…</div></div><ResetPassword v-else-if="resetToken" :token="resetToken" @done="resetDone"/><Login v-else-if="!user" @authenticated="authenticated"/><template v-else><aside><div class="brand"><b>Q</b><span>量化观察台<small>STOCK LAB</small></span></div><nav><button v-for="(label,key) in allowedLabels" :class="{active:currentView===key}" @click="navigate(key)">{{label}}</button></nav><div class="user-panel"><b>{{user.display_name}}</b><span>{{user.username}}</span><button @click="logout">退出登录</button></div><div class="status"><i></i>数据库已连接</div></aside><main><header><div><p>STOCK ANALYSIS</p><h1>{{labels[currentView]}}</h1></div><time>{{new Date().toLocaleDateString('zh-CN')}}</time></header><component :is="component" :user="user"/></main></template></template>
